@router.post("/api/v1/webhooks/stripe")
async def stripe_webhook_receiver(
    request: Request,
    stripe_signature: str = Header(..., alias="Stripe-Signature"),
    db: AsyncSession = Depends(get_async_db)
):
    payload = await request.body()
    try:
        event = stripe.Webhook.construct_event(
            payload, stripe_signature, settings.STRIPE_WEBHOOK_SECRET
        )
    except (ValueError, stripe.error.SignatureVerificationError):
        raise HTTPException(status_code=400, detail="Invalid signature")

    if event["type"] == "customer.subscription.updated":
        subscription = event["data"]["object"]
        stripe_customer_id = subscription.get("customer")
        new_tier = subscription["items"]["data"][0]["price"]["lookup_key"]

        stmt = select(Account).where(Account.stripe_customer_id == stripe_customer_id)
        res = await db.execute(stmt)
        account = res.scalar_one_or_none()
        if account:
            account.tier = new_tier
            account.subscription_status = subscription["status"]
            await db.commit()
    return {"received": True}
